//! Package 6's site rows (CPU-as-P1 fallback and roster game calls): generated by `tools/gen_sites_pkg6.py` from the
//! owned 13.0.5 `main` (the guard bytes) and checked against it by `tests/pkg6_sites.rs`. The
//! install line reports these after `sites::SITES`.

use super::guard::{SeamKind, GUARD_BYTES};
use super::sites::{Feature, Site};


pub static SITES: [Site; 12] = include!(concat!(env!("OUT_DIR"), "/tables/sites_pkg6.SITES.rs"));

/// The package's sites of one feature (all of them must be usable for the feature to install).
#[cfg(test)]
pub fn sites_of(feature: Feature) -> impl Iterator<Item = &'static Site> {
    SITES.iter().filter(move |site| site.feature == feature)
}

const _: () = assert!(GUARD_BYTES == 64);
